package e2ee

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// testdata/vectors.json is published in PROTOCOL.md. It was generated by an independent
// implementation; this test locks pkg/e2ee to it byte for byte, so a change that breaks
// compatibility with existing clients fails here.
type vectors struct {
	KDF struct {
		Passphrase string `json:"passphrase"`
		SaltB64    string `json:"salt_b64"`
		Iterations int    `json:"iterations"`
		KeyHex     string `json:"key_hex"`
	} `json:"kdf"`
	Event    sealVector `json:"event"`
	KeyCheck sealVector `json:"key_check"`
	Small    struct {
		PrefixHex     string `json:"prefix_hex"`
		Plaintext     string `json:"plaintext"`
		CiphertextHex string `json:"ciphertext_hex"`
	} `json:"file_small"`
	Empty struct {
		PrefixHex     string `json:"prefix_hex"`
		CiphertextHex string `json:"ciphertext_hex"`
	} `json:"file_empty"`
	Two struct {
		PrefixHex        string `json:"prefix_hex"`
		PlaintextSHA256  string `json:"plaintext_sha256"`
		CiphertextSize   int    `json:"ciphertext_size"`
		CiphertextSHA256 string `json:"ciphertext_sha256"`
	} `json:"file_two_segments"`
}

type sealVector struct {
	NonceHex      string `json:"nonce_hex"`
	Plaintext     string `json:"plaintext"`
	CiphertextB64 string `json:"ciphertext_b64"`
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestPublishedVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if v.KDF.Iterations != KDFIterations {
		t.Fatalf("vector iterations %d != KDFIterations %d", v.KDF.Iterations, KDFIterations)
	}
	salt, err := DecodeSalt(v.KDF.SaltB64)
	if err != nil {
		t.Fatal(err)
	}
	k, err := DeriveKey(v.KDF.Passphrase, salt)
	if err != nil {
		t.Fatal(err)
	}

	// Event payload and key check: exact bytes with the fixed nonce, and Open round trip.
	for name, sv := range map[string]sealVector{"event": v.Event, "key_check": v.KeyCheck} {
		nonce := mustHex(t, sv.NonceHex)
		got := base64.StdEncoding.EncodeToString(k.aead.Seal(append([]byte(nil), nonce...), nonce, []byte(sv.Plaintext), nil))
		if got != sv.CiphertextB64 {
			t.Errorf("%s: ciphertext mismatch\n got %s\nwant %s", name, got, sv.CiphertextB64)
		}
		plain, err := k.OpenBytes(sv.CiphertextB64)
		if err != nil || string(plain) != sv.Plaintext {
			t.Errorf("%s: open failed: %v", name, err)
		}
	}
	if !k.VerifyKeyCheck(v.KeyCheck.CiphertextB64) {
		t.Error("key check vector does not verify")
	}
	if p, err := k.Open(v.Event.CiphertextB64); err != nil || p.Title != "Hello" || p.URL != "https://example.com/" {
		t.Errorf("event payload decode: %+v %v", p, err)
	}

	// Files: exact ciphertext for fixed prefixes, and decryption back to the plaintext.
	checkFile := func(name string, prefix, plain, want []byte) {
		var out bytes.Buffer
		if err := k.encryptStream(&out, bytes.NewReader(plain), int64(len(plain)), prefix); err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		if want != nil && !bytes.Equal(out.Bytes(), want) {
			t.Errorf("%s: ciphertext mismatch", name)
		}
		var dec bytes.Buffer
		if _, err := k.DecryptStream(&dec, bytes.NewReader(out.Bytes())); err != nil || !bytes.Equal(dec.Bytes(), plain) {
			t.Errorf("%s: decrypt failed: %v", name, err)
		}
	}
	checkFile("file_small", mustHex(t, v.Small.PrefixHex), []byte(v.Small.Plaintext), mustHex(t, v.Small.CiphertextHex))
	checkFile("file_empty", mustHex(t, v.Empty.PrefixHex), nil, mustHex(t, v.Empty.CiphertextHex))

	big := make([]byte, 70000)
	for i := range big {
		big[i] = byte(i % 251)
	}
	if ps := sha256.Sum256(big); hex.EncodeToString(ps[:]) != v.Two.PlaintextSHA256 {
		t.Fatal("two-segment plaintext rule mismatch")
	}
	var out bytes.Buffer
	_ = k.encryptStream(&out, bytes.NewReader(big), int64(len(big)), mustHex(t, v.Two.PrefixHex))
	cs := sha256.Sum256(out.Bytes())
	if out.Len() != v.Two.CiphertextSize || hex.EncodeToString(cs[:]) != v.Two.CiphertextSHA256 {
		t.Errorf("two-segment ciphertext mismatch: size %d sha %x", out.Len(), cs)
	}
	if int64(v.Two.CiphertextSize) != EncryptedSize(int64(len(big))) {
		t.Error("EncryptedSize disagrees with vector")
	}
}
